SELECT c.id, c.user_id, c.model_id, c.parent_id, c.reply_to_user_id, c.content, c.created_at, u.id as u_id, u.username as u_username, u.avatar as u_avatar, ru.id as ru_id, ru.username as ru_username, ru.avatar as ru_avatar FROM comments c LEFT JOIN users u ON c.user_id = u.id LEFT JOIN users ru ON c.reply_to_user_id = ru.id WHERE c.parent_id IN
#{id}
ORDER BY c.created_at ASC
